<script setup>import{inject}from'vue';import{planFeatureGroups}from'../../../../config/planFeatures';const s=inject('planAdmin')</script><template><section class="admin-card"><div class="card-heading"><div><h2>Healthcare features</h2><p class="text-sm text-slate-500">Capabilities available under this plan.</p></div><RouterLink class="btn-secondary" :to="{name:'admin.plans.edit',params:{id:s.plan.value.id}}">Edit Features</RouterLink></div><div class="feature-groups"><section v-for="[group,items] in planFeatureGroups" :key="group"><h3 class="font-bold">{{group}}</h3><ul class="mt-3 space-y-2"><li v-for="[key,label] in items" :key="key" :class="s.plan.value.features?.[key]?'text-emerald-700':'text-slate-400'">{{s.plan.value.features?.[key]?'Enabled':'Disabled'}} &middot; {{label}}</li></ul></section></div></section></template>
